import{_ as t,o,c as r,a5 as u}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"Vue Router 和 组合式 API","description":"引入 setup 和 Vue 的组合式 API，开辟了新的可能性，但要想充分发挥 Vue Router 的潜力，我们需要使用一些新的函数来代替访问 this 和组件内导航守卫。 在 setup 中访问路由和当前路由 因为我们在 setup 里面没有访问 this，所以我们不能再直。","frontmatter":{"title":"Vue Router 和 组合式 API","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"引入 setup 和 Vue 的组合式 API，开辟了新的可能性，但要想充分发挥 Vue Router 的潜力，我们需要使用一些新的函数来代替访问 this 和组件内导航守卫。 在 setup 中访问路由和当前路由 因为我们在 setup 里面没有访问 this，所以我们不能再直。","sidebarWeight":12,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/Vue Router 和 组合式 API.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/Vue Router 和 组合式 API.md","filePath":"posts/Vue系统教程/04-路由与状态管理/Vue Router 和 组合式 API.md"}'),s={name:"posts/Vue系统教程/04-路由与状态管理/Vue Router 和 组合式 API.md"};function a(p,e,i,n,c,f){return o(),r("div",null,[...e[0]||(e[0]=[u('<div><h1 id="vue-router-和-组合式-api" tabindex="-1">Vue Router 和 组合式 API <a class="header-anchor" href="#vue-router-和-组合式-api" aria-label="Permalink to &quot;Vue Router 和 组合式 API&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue Router 和 组合式 API”的核心思路，并能把它用于实际开发或面试表达。 引入 setup 和 Vue 的组合式 API，开辟了新的可能性，但要想充分发挥 Vue Router 的潜力，我们需要使用一些新的函数来代替访问 this 和组件内导航守卫。</p></blockquote><p><strong>在 setup 中访问路由和当前路由</strong> 因为我们在 setup 里面没有访问 this，所以我们不能再直接访问 this.$router 或 this.$route。作为替代，我们使用 useRouter 和 useRoute 函数： import { useRouter, useRoute } from &#39;vue-router&#39; export default { setup() { const router = useRouter() const route = useRoute() function pushWithQuery(query) { router.push({ name: &#39;search&#39;, query: { ...route.query, }, }) } }, }</p><p>route 对象是一个响应式对象，所以它的任何属性都可以被监听，但你应该避免监听整个 route 对象。在大多数情况下，你应该直接监听你期望改变的参数。 import { useRoute } from &#39;vue-router&#39; import { ref, watch } from &#39;vue&#39; export default { setup() { const route = useRoute() const userData = ref() // 当参数更改时获取用户信息 watch( () =&gt; route.params.id, async newId =&gt; { userData.value = await fetchUser(newId) } ) }, } 请注意，在模板中我们仍然可以访问 $router 和 $route，所以不需要在 setup 中返回 router 或 route。</p><p><strong>导航守卫</strong> 虽然你仍然可以通过 setup 函数来使用组件内的导航守卫，但 Vue Router 将更新和离开守卫作为 组合式 API 函数公开： import { onBeforeRouteLeave, onBeforeRouteUpdate } from &#39;vue-router&#39; import { ref } from &#39;vue&#39; export default { setup() { // 与 beforeRouteLeave 相同，无法访问 <code>this</code> onBeforeRouteLeave((to, from) =&gt; { const answer = window.confirm( &#39;Do you really want to leave? you have unsaved changes!&#39; ) // 取消导航并停留在同一页面上 if (!answer) return false }) const userData = ref() // 与 beforeRouteUpdate 相同，无法访问 <code>this</code> onBeforeRouteUpdate(async (to, from) =&gt; { //仅当 id 更改时才获取用户，例如仅 query 或 hash 值已更改 if (to.params.id !== from.params.id) { userData.value = await fetchUser(to.params.id) } }) }, } 组合式 API 守卫也可以用在任何由 &lt;router-view&gt; 渲染的组件中，它们不必像组件内守卫那样直接用在路由组件上。</p><p>useLink Vue Router 将 RouterLink 的内部行为作为一个组合式函数 (composable) 公开。它接收一个类似 RouterLink 所有 prop 的响应式对象，并暴露底层属性来构建你自己的 RouterLink 组件或生成自定义链接： import { RouterLink, useLink } from &#39;vue-router&#39; import { computed } from &#39;vue&#39; export default { name: &#39;AppLink&#39;, props: { // 如果使用 TypeScript，请添加 @ts-ignore ...RouterLink.props, inactiveClass: String, }, setup(props) { const { // 解析出来的路由对象 route, // 用在链接里的 href href, // 布尔类型的 ref 标识链接是否为激活的 isActive, // 布尔类型的 ref 标识链接是否为严格活跃的 isExactActive, // 导航至该链接的函数 navigate } = useLink(props) const isExternalLink = computed( () =&gt; typeof props.to === &#39;string&#39; &amp;&amp; props.to.startsWith(&#39;http&#39;) ) return { isExternalLink, href, navigate, isActive } }, } 注意在 RouterLink 的 v-slot 中可以访问与 useLink 组合式函数相同的属性。</p></div>',1)])])}const R=t(s,[["render",a]]);export{m as __pageData,R as default};
